import 'package:flutter/material.dart';
import '../models/music_models.dart'; import '../services/musicbrainz_api.dart'; import '../widgets/state_views.dart'; import 'album_detail_page.dart';
class DiscographyPage extends StatefulWidget { const DiscographyPage({super.key,required this.artist}); final Artist artist; @override State<DiscographyPage> createState()=>_DiscographyPageState(); }
class _DiscographyPageState extends State<DiscographyPage>{ final _api=MusicBrainzApi(); late Future<List<ReleaseGroup>> _future; @override void initState(){super.initState();_future=_api.discography(widget.artist.id);} @override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:Text(widget.artist.name)),body:FutureBuilder<List<ReleaseGroup>>(future:_future,builder:(context,snapshot){if(snapshot.connectionState==ConnectionState.waiting)return const LoadingView(text:'Memuat diskografi...');if(snapshot.hasError)return ErrorView(message:snapshot.error.toString(),onRetry:()=>setState(()=>_future=_api.discography(widget.artist.id)));final albums=snapshot.data!;if(albums.isEmpty)return const Center(child:Text('Diskografi belum tersedia.'));return ListView.builder(padding:const EdgeInsets.all(16),itemCount:albums.length,itemBuilder:(context,index){final album=albums[index];return Card(child:ListTile(leading:Container(width:48,height:48,decoration:BoxDecoration(color:const Color(0xff9b8cff),borderRadius:BorderRadius.circular(12)),child:const Icon(Icons.album_rounded,color:Colors.black)),title:Text(album.title,style:const TextStyle(fontWeight:FontWeight.bold)),subtitle:Text('${album.primaryType??'Rilisan'} • ${album.firstReleaseDate??'Tanggal tidak tersedia'}'),trailing:const Icon(Icons.chevron_right),onTap:()=>Navigator.push(context,MaterialPageRoute(builder:(_)=>AlbumDetailPage(album:album)))));});})); }
